import re
import sys

assignment = re.compile(
    r"([a-p]|TMP)\s*<-\s*"
    r"(?:(\d+)|\(\s*\1\s*\+\s*(\d+)\s*\)\s*mod\s*100)\s*;"
)

values = {}

for line in sys.stdin:
    match = assignment.fullmatch(line.strip())
    if not match:
        continue

    name, initial, increment = match.groups()
    if initial is not None:
        values[name] = int(initial)
    else:
        values[name] = (values[name] + int(increment)) % 100

names = [*map(chr, range(ord("a"), ord("p") + 1)), "TMP"]
print(" ".join(f"{name} ?= {values[name]};" for name in names))
